package app.cryptoresearch.mobile;
import android.app.*;import android.content.*;import android.os.*;import android.graphics.Color;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.util.concurrent.*;
public class BackgroundActivity extends Activity {
 final Handler handler=new Handler(Looper.getMainLooper());final ExecutorService io=Executors.newSingleThreadExecutor();LinearLayout body,analytics;EditText url,token,capital,fee,slip;TextView localStatus,remoteStatus;boolean visible,busy,canControl;String verifiedAddress="",verifiedToken="";long lastRemotePoll;
 int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}TextView text(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(Color.rgb(27,34,48));t.setPadding(0,dp(5),0,dp(5));return t;}
 LinearLayout card(){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(dp(20),dp(18),dp(20),dp(18));GradientDrawable d=new GradientDrawable();d.setColor(Color.WHITE);d.setCornerRadius(dp(24));c.setBackground(d);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(18);body.addView(c,p);return c;}
 Button button(LinearLayout c,String title,Runnable run){Button b=new Button(this);b.setText(title);b.setAllCaps(false);b.setMinHeight(dp(48));b.setOnClickListener(v->run.run());c.addView(b);return b;}
 EditText field(LinearLayout c,String title,String value,int input){c.addView(text(title,12));EditText e=new EditText(this);e.setText(value);e.setInputType(input);e.setSingleLine();e.setMinHeight(dp(48));c.addView(e);return e;}
 public void onCreate(Bundle b){super.onCreate(b);ScrollView scroll=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setBackgroundColor(Color.rgb(245,247,251));body.setPadding(dp(20),dp(16),dp(20),dp(20));scroll.addView(body);scroll.setOnApplyWindowInsetsListener((v,i)->{if(Build.VERSION.SDK_INT>=30){android.graphics.Insets x=i.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout());v.setPadding(x.left,x.top,x.right,x.bottom);}else{v.setPadding(i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());}return i;});setContentView(scroll);scroll.requestApplyInsets();body.addView(text("백그라운드 · Ubuntu 서버",28));button(body,"돌아가기",()->finish());LinearLayout local=card();local.addView(text("이 기기에서 모의 실행",21));local.addView(text("중지 알림이 있는 서비스로 화면 밖에서도 선택 종목을 관측합니다. 배터리를 사용하며 Android15 시간 제한과 OS 중단이 적용됩니다. 최대5시간45분 후 정지합니다. 24시간 실행은 Ubuntu 서버를 사용하세요.",13));String symbol=getSharedPreferences("workspace-v1",MODE_PRIVATE).getString("coin","BTC");local.addView(text("선택 종목 "+symbol+" · KRW",14));capital=field(local,"시작 모의 자본 KRW","1000000",8194);fee=field(local,"수수료 bps","5",8194);slip=field(local,"슬리피지 bps","5",8194);button(local,"기기 백그라운드 모의세션 시작",()->startLocal(symbol));button(local,"기기 모의세션 중지",()->{startService(new Intent(this,PaperBackgroundService.class).setAction(PaperBackgroundService.STOP));});localStatus=text(PaperBackgroundService.status,13);local.addView(localStatus);button(local,"마지막 기기 리포트 보기",()->loadLocalReport());LinearLayout remote=card();remote.addView(text("Ubuntu 서버 연결",21));remote.addView(text("휴대폰이 꺼져도 서버에서 모의전략이 계속 실행됩니다. HTTPS와 서버 접근 토큰이 필요합니다. 거래소 API 키를 입력하지 마세요.",13));url=field(remote,"HTTPS 서버 기본 주소",getSharedPreferences("paper-server",MODE_PRIVATE).getString("url",""),android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_URI);String saved="";try{saved=ServerVault.read(this);}catch(Exception ignored){}token=field(remote,"VIEW_TOKEN 또는 CONTROL_TOKEN",saved,android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD);verifiedAddress=url.getText().toString();verifiedToken=saved;button(remote,"서버 설정 저장",()->{try{String u=PaperServerAPI.canonical(url.getText().toString());String t=token.getText().toString();if(t.length()<32||t.length()>512)throw new Exception();ServerVault.save(this,t);getSharedPreferences("paper-server",MODE_PRIVATE).edit().putString("url",u).apply();url.setText(u);verifiedAddress=u;verifiedToken=t;remoteStatus.setText("저장했어요. 서버 상태를 확인하세요.");}catch(Exception e){remoteStatus.setText("주소·토큰 또는 기기 보안 저장소 확인 필요");}});button(remote,"기기에서 토큰 삭제",()->{ServerVault.clear(this);token.setText("");verifiedToken="";canControl=false;remoteStatus.setText("기기의 토큰만 삭제했습니다. 서버 세션은 유지됩니다.");});button(remote,"서버 상태 확인",()->call("api/v1/status",null));button(remote,"새 서버 모의세션 시작",()->{if(!canControl){remoteStatus.setText("서버 상태 확인 후 제어 토큰 권한이 있어야 합니다.");return;}try{double c=Double.parseDouble(capital.getText().toString()),f=Double.parseDouble(fee.getText().toString()),s=Double.parseDouble(slip.getText().toString());new StrategyCore(c,f,s);if(c>1e15)throw new Exception();call("api/v1/sessions/start",new JSONObject().put("symbol",symbol).put("capital",c).put("fee_bps",f).put("slip_bps",s));}catch(Exception e){remoteStatus.setText("자본/비용 입력을 확인하세요");}});button(remote,"서버 모의세션 정지",()->{if(canControl)call("api/v1/sessions/pause",new JSONObject());else remoteStatus.setText("제어 권한이 필요합니다.");});button(remote,"서버 리포트 보기",()->call("api/v1/report",null));remoteStatus=text("연결 안 됨",13);remoteStatus.setTextIsSelectable(true);remote.addView(remoteStatus);analytics=card();analytics.addView(text("기기/서버 리포트는 별도 모의계좌입니다. 실제 주문은 없습니다.",12));}
 void startLocal(String symbol){try{double c=Double.parseDouble(capital.getText().toString()),f=Double.parseDouble(fee.getText().toString()),s=Double.parseDouble(slip.getText().toString());new StrategyCore(c,f,s);if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},130);Intent i=new Intent(this,PaperBackgroundService.class).setAction(PaperBackgroundService.START).putExtra("symbol",symbol).putExtra("capital",c).putExtra("fee",f).putExtra("slip",s);startForegroundService(i);localStatus.setText("서비스 시작 요청 · 중지 알림을 확인하세요");}catch(Exception e){localStatus.setText("기기 실행 시작 불가 · 입력/OS 제한 확인 필요");}}
 void loadLocalReport(){try{File f=new File(getFilesDir(),"background-paper-last.json");if(!f.exists()||f.length()>8*1024*1024)throw new Exception();byte[] raw=java.nio.file.Files.readAllBytes(f.toPath());analytics.removeAllViews();analytics.addView(text("저장된 기기 리포트 · 자동 재개하지 않음",14));analytics.addView(new ResearchAnalyticsView(this,raw));}catch(Exception e){localStatus.setText("저장된 기기 리포트가 없거나 읽을 수 없습니다.");}}
 void call(String path,JSONObject payload){if(busy)return;String base=url.getText().toString(),secret=token.getText().toString();busy=true;remoteStatus.setText("서버 확인 중");io.execute(()->{try{byte[] data=PaperServerAPI.request(base,secret,path,payload);JSONObject j=new JSONObject(new String(data,java.nio.charset.StandardCharsets.UTF_8));handler.post(()->{busy=false;if(isDestroyed())return;if(path.equals("api/v1/report")){analytics.removeAllViews();analytics.addView(text("Ubuntu 서버 모의 리포트 · "+j.optString("session_symbol","—"),18));analytics.addView(new ResearchAnalyticsView(this,data));remoteStatus.setText("서버 리포트를 가져왔어요.");}else{if(!"SERVER_PAPER_ONLY".equals(j.optString("mode"))||j.optBoolean("live_orders_supported",true)){remoteStatus.setText("지원하는 모의 서버가 아닙니다.");canControl=false;return;}canControl=j.optBoolean("can_control");remoteStatus.setText("서버 "+j.optString("state")+" · "+j.optString("symbol","—")+"\n준비 "+Math.min(30,j.optInt("bars"))+"/30봉 · "+(canControl?"제어 가능":"읽기 전용")+"\n"+j.optString("reason")+"\n휴대폰 미접속 중에도 서버 세션은 유지됩니다.");}});}catch(Exception e){handler.post(()->{busy=false;canControl=false;if(!isDestroyed())remoteStatus.setText("연결 실패 · 주소/HTTPS/토큰 확인: "+e.getMessage());});}});}
 boolean autoRefreshAllowed(){return !verifiedAddress.isEmpty()&&!verifiedToken.isEmpty()&&verifiedAddress.equals(url.getText().toString())&&verifiedToken.equals(token.getText().toString());}
 final Runnable poll=new Runnable(){public void run(){if(!visible)return;if(!busy&&autoRefreshAllowed()&&SystemClock.elapsedRealtime()-lastRemotePoll>=10000){lastRemotePoll=SystemClock.elapsedRealtime();call("api/v1/status",null);}StrategyCore.Live p=PaperBackgroundService.session;localStatus.setText((PaperBackgroundService.active?"기기 실행 중":"기기 정지")+" · "+PaperBackgroundService.status+(p==null?"":"\n준비 "+Math.min(30,p.engine.bars)+"/30봉 · 모의 보유 "+p.engine.qty));handler.postDelayed(this,1000);}};
 public void onStart(){super.onStart();visible=true;handler.post(poll);if(autoRefreshAllowed()){lastRemotePoll=SystemClock.elapsedRealtime();call("api/v1/status",null);}}public void onStop(){visible=false;handler.removeCallbacks(poll);super.onStop();}public void onDestroy(){handler.removeCallbacksAndMessages(null);io.shutdownNow();super.onDestroy();}
}
